mat2 rot(float a) { float s = sin(a), c = cos(a); return mat2(c, -s, s, c); }
float sdBox(vec3 p, vec3 b) {
  vec3 q = abs(p) - b;
  return length(max(q, 0.0)) + min(max(q.x, max(q.y, q.z)), 0.0);
}
float map(vec3 p) {
  p.xz = rot(time * 0.2) * p.xz;
  vec3 q = p;
  float m = sdBox(q, vec3(0.5, 1.6, 0.25));
  m = max(m, -sdBox(q - vec3(0.0, 0.0, 0.2), vec3(0.35, 1.4, 0.1)));
  float base = sdBox(p + vec3(0.0, 1.6, 0.0), vec3(1.2, 0.1, 1.2));
  return min(m, base);
}
shader_body {
  vec2 p = (uv - 0.5) * vec2(aspect.x, 1.0) * 2.0;
  vec3 ro = vec3(0.0, 0.2, -3.8);
  vec3 rd = normalize(vec3(p, 1.8));
  float t = 0.0;
  for (int i = 0; i < 50; i++) {
    float d = map(ro + rd * t);
    if (d < 0.002 || t > 9.0) break;
    t += d * 0.8;
  }
  vec3 col = vec3(0.01, 0.02, 0.04) + vec3(0.0, 0.1, 0.2) * (1.0 - uv.y);
  if (t < 9.0) {
    vec3 pos = ro + rd * t;
    vec2 e = vec2(0.004, 0.0);
    vec3 n = normalize(vec3(
      map(pos + e.xyy) - map(pos - e.xyy),
      map(pos + e.yxy) - map(pos - e.yxy),
      map(pos + e.yyx) - map(pos - e.yyx)
    ));
    vec3 l = normalize(vec3(1.0, 1.5, -2.0));
    float diff = max(dot(n, l), 0.0);
    float spec = pow(max(dot(reflect(-l, n), -rd), 0.0), 32.0);
