    vec3 jadeGlow = vec3(0.0, 0.9, 0.5) * (sin(pos.y * 12.0 + time * 3.0) * 0.5 + 0.5) * bass;
    col = vec3(0.02, 0.03, 0.05) + diff * vec3(0.1, 0.3, 0.4) + spec * vec3(0.9, 1.0, 0.9) + rim * vec3(0.0, 0.8, 0.6) + jadeGlow;
  }
  ret = col;
}
